from collections import Counter

def transform_demo1(grid):
    h, w = len(grid), len(grid[0])

    counts = Counter(c for row in grid for c in row)
    bg = max(counts, key=counts.get)

    colors = sorted(set(c for row in grid for c in row if c != bg))
    n = len(colors)

    out = [[bg] * w for _ in range(h)]

    if n == 4:
        for k, color in enumerate(colors):
            if k < n - 1:
                # For k < n-1:
                # Column c=k: rows r from k to k+2 (3 rows)
                # Column c=k+1: row r = k only (1 row, but need to verify)
                for c, row_set in [(k, set(range(k, k+3))), (k+1, set([k]))]:
                    if c < w:
                        for r in row_set:
                            if r < h:
                                out[r][c] = color
            else:
                # k == n-1: column c=k, rows from k+2 to k+6 (4 rows)
                col = k
                if col < w:
                    for r in range(k + 2, min(h, k + 7)):
                        out[r][col] = color

    return out

